[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$CapturePath,[Parameter(Mandatory=$true)][string]$OutputPath)
$ErrorActionPreference='Stop';$c=Get-Content $CapturePath -Raw -Encoding UTF8|ConvertFrom-Json;$block=@();$reason=$null;if($c.provenance-eq'LIVE_READONLY'){$reason='LIVE_SNAPSHOT_INDEPENDENT_BINDING_REQUIRED'};if(-not$c.stateEligible){$block+='CAPTURE_NOT_ELIGIBLE'};$sx=[single]$c.coordinateFrame.scaleX;$sy=[single]$c.coordinateFrame.scaleY;if(-not[float]::IsFinite($sx)-or-not[float]::IsFinite($sy)-or$sx-le0-or$sy-le0){$block+='INVALID_SCALE'}
function Trunc([double]$v){[int][Math]::Truncate($v)};function Axis($lo,$hi,$scale,$limit){$inside=@();for($p=0;$p-lt$limit;$p++){$v=Trunc($p*$scale);if($v-ge$lo-and$v-lt$hi){$inside+=$p}};if($inside.Count-eq0){return $null};[ordered]@{first=$inside[0];lastExclusive=$inside[-1]+1}}
function Region($surface){$x=Axis $surface.logicalRect.left $surface.logicalRect.right $sx $c.process.clientWidth;$y=Axis $surface.logicalRect.top $surface.logicalRect.bottom $sy $c.process.clientHeight;if($null-eq$x-or$null-eq$y){$script:block+='BOUND_AUTHORITY_CARD_SURFACE_NO_CLIENT_PIXELS';return $null};if(($x.lastExclusive-$x.first)-lt3-or($y.lastExclusive-$y.first)-lt3){$script:block+='BOUND_AUTHORITY_CARD_SURFACE_NO_3X3_SAFE_MARGIN';return $null};$px=[int][Math]::Floor(($x.first+$x.lastExclusive-1)/2);$py=[int][Math]::Floor(($y.first+$y.lastExclusive-1)/2);[ordered]@{surface=$surface.surface;widgetPointer=$surface.widgetPointer;logicalRect=$surface.logicalRect;clientRect=[ordered]@{left=$x.first;top=$y.first;right=$x.lastExclusive;bottom=$y.lastExclusive};safePoint=[ordered]@{x=$px;y=$py;forwardLogical=[ordered]@{x=Trunc($px*$sx);y=Trunc($py*$sy)}}}}
$regions=@();if(-not$reason-and$block.Count-eq0){$r=Region $c.selectedAuthorityCard.activeSurface;if($null-ne$r){$regions+=,$r}};$status=if($reason-or$block.Count){'UNBOUND'}else{'OFFLINE_RESOLVED'};$out=[ordered]@{schemaVersion=1;status=$status;reason=$reason;sourceProvenance=$c.provenance;originalRuntimeObserved=$false;selectedAuthorityCard=[ordered]@{index=$c.selectedAuthorityCard.index;cardId=$c.selectedAuthorityCard.cardId;semantic=$c.selectedAuthorityCard.semantic;regions=$regions};automaticActivationPoint=$null;selectionPolicy='PAGE_TABLE_SELECTS_EXACT_SCANNER_SURFACE_NO_AUTOMATIC_INPUT';blockers=@($block);operations=[ordered]@{writes=0;gameInputs=0}};$dir=Split-Path $OutputPath;if($dir-and-not(Test-Path $dir)){New-Item -ItemType Directory $dir|Out-Null};$out|ConvertTo-Json -Depth 15|Set-Content $OutputPath -Encoding UTF8
